LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
BEGIN
 IF NOT photo.begin_editor_final_before_billing(p_tenant,p_build,p_run,p_workflow,p_config,p_policy,p_bytes,p_pin) THEN RETURN false;END IF;
 PERFORM photo.billing_link_editor_children(p_tenant,p_build);RETURN true;
END $$;
-- +goose StatementEnd
ALTER FUNCTION photo.seal_v2_graph(uuid,uuid) RENAME TO seal_v2_graph_before_editor_billing;
REVOKE ALL ON FUNCTION photo.seal_v2_graph_before_editor_billing(uuid,uuid) FROM PUBLIC,photo_api,photo_scheduler,photo_worker;
-- +goose StatementBegin
CREATE FUNCTION photo.seal_v2_graph(p_tenant uuid,p_run uuid) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
BEGIN
 IF EXISTS(SELECT 1 FROM photo.billing_editor_controls WHERE tenant_id=p_tenant AND enabled)
 AND EXISTS(SELECT 1 FROM photo.editor_effect_builds WHERE tenant_id=p_tenant AND final_run_id=p_run)
 AND NOT EXISTS(SELECT 1 FROM photo.editor_effect_builds b JOIN photo.billing_usage_requests req ON req.tenant_id=b.tenant_id AND req.run_id=b.run_id AND req.workflow_kind='editor_effects' AND req.status='accepted'
 JOIN photo.billing_usage_charge_items ci ON ci.tenant_id=req.tenant_id AND ci.usage_request_id=req.id
 JOIN photo.billing_usage_tickets ti ON ti.tenant_id=ci.tenant_id AND ti.charge_item_id=ci.id AND ti.state='accepted'
 WHERE b.tenant_id=p_tenant AND b.final_run_id=p_run) THEN RETURN false;END IF;
 RETURN photo.seal_v2_graph_before_editor_billing(p_tenant,p_run);
END $$;
