ALTER FUNCTION photo.begin_editor_effect_final_render(uuid,uuid,uuid,uuid,text,text,bigint,jsonb) OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.begin_editor_effect_final_render(uuid,uuid,uuid,uuid,text,text,bigint,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION photo.begin_editor_effect_final_render(uuid,uuid,uuid,uuid,text,text,bigint,jsonb) TO photo_scheduler;
-- Row SHARE requires UPDATE privilege; only the non-login definer receives it.
GRANT UPDATE(id) ON photo.v2_documents,photo.v2_document_streams TO photo_fn_owner;
-- Existing Go Editor admission expects this lock boundary. Pin the immutable
-- frozen recipe and its draft document while rechecking current authorization.
-- Additive bridge: preserve exact native actor/session locking authority.
-- +goose StatementBegin
DO $bridge$
DECLARE old pg_catalog.pg_proc%ROWTYPE;caller pg_catalog.text;
BEGIN
 IF pg_catalog.to_regprocedure('photo.lock_editor_effect_identity_before_billing(uuid,uuid,uuid,uuid,text,uuid,text,uuid,uuid,bigint,uuid,uuid)') IS NOT NULL THEN RAISE EXCEPTION 'EDITOR_BILLING_IDENTITY_ALIAS_OCCUPIED';END IF;
 SELECT * INTO old FROM pg_catalog.pg_proc WHERE oid=pg_catalog.to_regprocedure('photo.lock_editor_effect_identity(uuid,uuid,uuid,uuid,text,uuid,text,uuid,uuid,bigint,uuid,uuid)');
 IF FOUND THEN
  IF old.proowner<>(SELECT oid FROM pg_catalog.pg_roles WHERE rolname='photo_fn_owner') OR old.prolang<>(SELECT oid FROM pg_catalog.pg_language WHERE lanname='plpgsql') OR ARRAY(SELECT unnest(old.proargtypes)) IS DISTINCT FROM ARRAY['pg_catalog.uuid'::pg_catalog.regtype::pg_catalog.oid,'pg_catalog.uuid'::pg_catalog.regtype::pg_catalog.oid,'pg_catalog.uuid'::pg_catalog.regtype::pg_catalog.oid,'pg_catalog.uuid'::pg_catalog.regtype::pg_catalog.oid,'pg_catalog.text'::pg_catalog.regtype::pg_catalog.oid,'pg_catalog.uuid'::pg_catalog.regtype::pg_catalog.oid,'pg_catalog.text'::pg_catalog.regtype::pg_catalog.oid,'pg_catalog.uuid'::pg_catalog.regtype::pg_catalog.oid,'pg_catalog.uuid'::pg_catalog.regtype::pg_catalog.oid,'pg_catalog.int8'::pg_catalog.regtype::pg_catalog.oid,'pg_catalog.uuid'::pg_catalog.regtype::pg_catalog.oid,'pg_catalog.uuid'::pg_catalog.regtype::pg_catalog.oid]::pg_catalog.oid[] OR old.proallargtypes IS NOT NULL OR old.proargdefaults IS NOT NULL OR old.proargmodes IS NOT NULL OR old.probin IS NOT NULL OR old.prosqlbody IS NOT NULL OR old.protrftypes IS NOT NULL OR old.procost IS DISTINCT FROM 100 OR old.pronargdefaults IS DISTINCT FROM 0 OR old.pronargs IS DISTINCT FROM 12 OR old.prorows IS DISTINCT FROM 0 OR old.proisstrict IS DISTINCT FROM false OR old.proleakproof IS DISTINCT FROM false OR old.proretset IS DISTINCT FROM false OR old.prosecdef IS DISTINCT FROM true OR old.prokind IS DISTINCT FROM 'f' OR old.proparallel IS DISTINCT FROM 'u' OR old.provolatile IS DISTINCT FROM 'v' OR old.prorettype<>'pg_catalog.bool'::pg_catalog.regtype OR old.provariadic<>0 OR old.prosupport<>0 OR old.proconfig IS DISTINCT FROM ARRAY['search_path=pg_catalog, photo']::pg_catalog.text[] OR old.proargnames IS DISTINCT FROM ARRAY['p_tenant','p_project','p_version','p_source','p_source_sha','p_recipe','p_recipe_sha','p_frozen','p_draft','p_revision','p_actor','p_session']::pg_catalog.text[] OR encode(sha256(convert_to(old.prosrc,'UTF8')),'hex')<>'0862401fb8355863cb9dcf47a5f4faf64dd8538bee0c2765b039bcfbd6a01478' OR old.proacl IS DISTINCT FROM ARRAY['photo_fn_owner=X/photo_fn_owner','photo_api=X/photo_fn_owner']::pg_catalog.aclitem[] THEN RAISE EXCEPTION 'EDITOR_BILLING_NATIVE_IDENTITY_DRIFT';END IF;
  FOREACH caller IN ARRAY ARRAY['photo_api','photo_worker','photo_scheduler','photo_auth','photo_portal','photo_maintenance'] LOOP
   IF pg_catalog.has_function_privilege(caller,old.oid,'EXECUTE') IS DISTINCT FROM (caller='photo_api') THEN RAISE EXCEPTION 'EDITOR_BILLING_NATIVE_CALLER_DRIFT';END IF;
  END LOOP;
  ALTER FUNCTION photo.lock_editor_effect_identity(uuid,uuid,uuid,uuid,text,uuid,text,uuid,uuid,bigint,uuid,uuid) RENAME TO lock_editor_effect_identity_before_billing;
 ELSE
  EXECUTE $create$CREATE FUNCTION photo.lock_editor_effect_identity_before_billing(p_tenant uuid,p_project uuid,p_version uuid,p_source uuid,p_source_sha text,p_recipe uuid,p_recipe_sha text,p_frozen uuid,p_draft uuid,p_revision bigint,p_actor uuid,p_session uuid) RETURNS boolean LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,photo AS $native$
BEGIN
 -- Do not expose arbitrary global actor/session row locks to an API caller.
 IF photo.editor_effect_origin_scope(p_tenant,p_project,p_version,p_source,p_source_sha,p_recipe,p_recipe_sha,p_frozen,p_draft,p_revision,p_actor,p_session) IS NOT TRUE THEN RETURN false;END IF;
 PERFORM id FROM photo.users WHERE id=p_actor FOR SHARE;
 IF NOT FOUND THEN RETURN false;END IF;
 PERFORM id FROM photo.sessions WHERE id=p_session AND user_id=p_actor FOR SHARE;
 IF NOT FOUND THEN RETURN false;END IF;
 -- READ COMMITTED may have waited for a concurrent disable/revoke. Revalidate
 -- the complete original source/editor/session authority after both waits.
 RETURN photo.editor_effect_origin_scope(p_tenant,p_project,p_version,p_source,p_source_sha,p_recipe,p_recipe_sha,p_frozen,p_draft,p_revision,p_actor,p_session) IS TRUE;
END $native$;$create$;
  ALTER FUNCTION photo.lock_editor_effect_identity_before_billing(uuid,uuid,uuid,uuid,text,uuid,text,uuid,uuid,bigint,uuid,uuid) OWNER TO photo_fn_owner;
  REVOKE ALL ON FUNCTION photo.lock_editor_effect_identity_before_billing(uuid,uuid,uuid,uuid,text,uuid,text,uuid,uuid,bigint,uuid,uuid) FROM PUBLIC;
  GRANT EXECUTE ON FUNCTION photo.lock_editor_effect_identity_before_billing(uuid,uuid,uuid,uuid,text,uuid,text,uuid,uuid,bigint,uuid,uuid) TO photo_api;
 END IF;
 -- Alias is internal-only: original API entry retains the public admission boundary.
 REVOKE ALL ON FUNCTION photo.lock_editor_effect_identity_before_billing(uuid,uuid,uuid,uuid,text,uuid,text,uuid,uuid,bigint,uuid,uuid) FROM PUBLIC,photo_api,photo_scheduler,photo_worker,photo_auth,photo_portal,photo_maintenance;
END $bridge$;
-- +goose StatementEnd
-- +goose StatementBegin
CREATE FUNCTION photo.lock_editor_effect_identity(p_tenant uuid,p_project uuid,p_version uuid,p_source uuid,p_source_sha text,p_recipe uuid,p_recipe_sha text,p_frozen uuid,p_draft uuid,p_revision bigint,p_actor uuid,p_session uuid) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
BEGIN
 IF photo.lock_editor_effect_identity_before_billing(p_tenant,p_project,p_version,p_source,p_source_sha,p_recipe,p_recipe_sha,p_frozen,p_draft,p_revision,p_actor,p_session) IS NOT TRUE THEN RETURN false;END IF;
 PERFORM u.document_id FROM photo.v2_draft_uploads u WHERE u.tenant_id=p_tenant AND u.document_id=p_frozen FOR SHARE;
 IF NOT FOUND THEN RETURN false;END IF;
 PERFORM d.id FROM photo.v2_documents d JOIN photo.v2_document_streams s ON s.tenant_id=d.tenant_id AND s.id=d.stream_id
 WHERE d.tenant_id=p_tenant AND d.id=p_draft FOR SHARE OF d,s;
 IF NOT FOUND THEN RETURN false;END IF;
 PERFORM a.id FROM photo.artifacts a WHERE a.tenant_id=p_tenant AND a.id IN(p_source,p_recipe) ORDER BY a.id FOR SHARE;
 RETURN photo.lock_editor_effect_identity_before_billing(p_tenant,p_project,p_version,p_source,p_source_sha,p_recipe,p_recipe_sha,p_frozen,p_draft,p_revision,p_actor,p_session) IS TRUE;
END $$;
-- +goose StatementEnd
